CREATE OR REPLACE PROCEDURE USP_INBOX_PARTICIPES(
    p_id             IN NUMBER,
    p_aggregate_type IN VARCHAR2,
    p_source_table   IN VARCHAR2,
    p_event_type     IN VARCHAR2,
    p_payload        IN CLOB
) AS
    v_err  VARCHAR2(4000);
    v_pk   VARCHAR2(200);
    v_tipo VARCHAR2(50);
BEGIN

    -- personaTelefonosType  <-  fctbafil_actu  ->  PERSONATELEFONOSTYPE  (multi-row)
    IF p_aggregate_type = 'personaTelefonosType' AND p_source_table = 'fctbafil_actu' THEN
        BEGIN
            v_pk := JSON_VALUE(p_payload, '$.ci_cedu');
            v_tipo := JSON_VALUE(p_payload, '$.ci_tipo');
            IF p_event_type IN ('DELETE','DELETED') THEN
                IF v_pk IS NOT NULL THEN
                    DELETE FROM PERSONATELEFONOSTYPE WHERE IDENTIFICACION = v_pk;
                END IF;
            ELSIF v_pk IS NOT NULL THEN
                FOR f IN (
                    SELECT '1' AS sec, 'CONV' AS tip, JSON_VALUE(p_payload,'$.tx_telf_conv') AS num FROM dual
                    UNION ALL SELECT '2','CEL', JSON_VALUE(p_payload,'$.tx_telf_celu') FROM dual
                    UNION ALL SELECT '3','CON1', JSON_VALUE(p_payload,'$.tx_telf_con1') FROM dual
                    UNION ALL SELECT '4','CON2', JSON_VALUE(p_payload,'$.tx_telf_con2') FROM dual
                ) LOOP
                    IF f.num IS NOT NULL AND TRIM(f.num) IS NOT NULL THEN
                        MERGE INTO PERSONATELEFONOSTYPE t
                        USING (SELECT v_pk AS k, f.sec AS sec FROM dual) s
                        ON (t.IDENTIFICACION = s.k AND t.SECUENCIATELEFONO = s.sec)
                        WHEN MATCHED THEN UPDATE SET
                            CODIGOTIPOIDENTIFICACION = v_tipo,
                            CODIGOTIPOTELEFONO = f.tip,
                            NUMEROTELEFONO = f.num,
                            FECHAINGRESO = JSON_VALUE(p_payload,'$.fe_ingr'),
                            EMPRESAOPERADORA = CASE WHEN f.tip='CEL' THEN JSON_VALUE(p_payload,'$.ti_oper') ELSE NULL END
                        WHEN NOT MATCHED THEN INSERT
                            (CODIGOTIPOIDENTIFICACION, IDENTIFICACION, SECUENCIATELEFONO,
                             CODIGOTIPOTELEFONO, NUMEROTELEFONO, FECHAINGRESO, EMPRESAOPERADORA)
                        VALUES (v_tipo, v_pk, f.sec, f.tip, f.num,
                                JSON_VALUE(p_payload,'$.fe_ingr'),
                                CASE WHEN f.tip='CEL' THEN JSON_VALUE(p_payload,'$.ti_oper') ELSE NULL END);
                    END IF;
                END LOOP;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_err := SQLERRM;
            INSERT INTO CDC_INBOX_ERRORS (INBOX_ID, AGGREGATE_TYPE, EVENT_TYPE, ERROR_MESSAGE)
            VALUES (p_id, p_aggregate_type, p_event_type, 'PERSONATELEFONOSTYPE: ' || SUBSTR(v_err,1,3900));
        END;
    END IF;


    -- personaDireccionesType  <-  cgtbprvd  ->  PERSONADIRECCIONESTYPE
    IF p_aggregate_type = 'personaDireccionesType' AND p_source_table = 'cgtbprvd' THEN
        BEGIN
            v_pk := JSON_VALUE(p_payload, '$.ti_iden');
            IF p_event_type IN ('DELETE','DELETED') THEN
                IF v_pk IS NOT NULL THEN
                    DELETE FROM PERSONADIRECCIONESTYPE WHERE IDENTIFICACION = v_pk;
                END IF;
            ELSIF v_pk IS NOT NULL THEN
                MERGE INTO PERSONADIRECCIONESTYPE t
                USING (SELECT v_pk AS k, JSON_VALUE(p_payload,'$.ds_dire') AS sec FROM dual) s
                ON (t.IDENTIFICACION = s.k AND t.NUMERODIRECCION = s.sec)
                WHEN MATCHED THEN UPDATE SET CODIGOTIPOIDENTIFICACION = JSON_VALUE(p_payload,'$.ti_iden'), CODIGOTIPODIRECCION = JSON_VALUE(p_payload,'$.ds_dire'), CODIGOPAIS = NULL, CODIGOPROVINCIA = NULL, CODIGOCIUDAD = NULL, DIRECCIONPRINCIPAL = JSON_VALUE(p_payload,'$.ds_dire'), CALLE = NULL, NUMERO = NULL, INMUEBLE = NULL, DEPARTAMENTO = NULL, URBANIZACION = NULL, DIRECCION = JSON_VALUE(p_payload,'$.ds_dire'), FECHAINGRESO = JSON_VALUE(p_payload,'$.fe_ingr'), FECHAINGRESORESIDENCIA = JSON_VALUE(p_payload,'$.ti_iden'), OBSERVACIONES = NULL, CODIGOPARROQUIA = NULL, CODIGOCANTON = NULL, CODIGOBARRIO = NULL, TRANSVERSAL = NULL, CODIGOTIPOSITIO = NULL, SECTOR = NULL, CODIGOZIP5 = NULL, NOMBREPROPIETARIO = NULL
                WHEN NOT MATCHED THEN INSERT (CODIGOTIPOIDENTIFICACION, IDENTIFICACION, NUMERODIRECCION, CODIGOTIPODIRECCION, CODIGOPAIS, CODIGOPROVINCIA, CODIGOCIUDAD, DIRECCIONPRINCIPAL, CALLE, NUMERO, INMUEBLE, DEPARTAMENTO, URBANIZACION, DIRECCION, FECHAINGRESO, FECHAINGRESORESIDENCIA, OBSERVACIONES, CODIGOPARROQUIA, CODIGOCANTON, CODIGOBARRIO, TRANSVERSAL, CODIGOTIPOSITIO, SECTOR, CODIGOZIP5, NOMBREPROPIETARIO) VALUES (JSON_VALUE(p_payload,'$.ti_iden'), JSON_VALUE(p_payload,'$.ti_iden'), JSON_VALUE(p_payload,'$.ds_dire'), JSON_VALUE(p_payload,'$.ds_dire'), NULL, NULL, NULL, JSON_VALUE(p_payload,'$.ds_dire'), NULL, NULL, NULL, NULL, NULL, JSON_VALUE(p_payload,'$.ds_dire'), JSON_VALUE(p_payload,'$.fe_ingr'), JSON_VALUE(p_payload,'$.ti_iden'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_err := SQLERRM;
            INSERT INTO CDC_INBOX_ERRORS (INBOX_ID, AGGREGATE_TYPE, EVENT_TYPE, ERROR_MESSAGE)
            VALUES (p_id, p_aggregate_type, p_event_type, 'PERSONADIRECCIONESTYPE: ' || SUBSTR(v_err,1,3900));
        END;
    END IF;


    -- personaReferenciasBancariasType  <-  cgtbprvd  ->  PERSONAREFERENCIASBANCARIASTYPE
    IF p_aggregate_type = 'personaReferenciasBancariasType' AND p_source_table = 'cgtbprvd' THEN
        BEGIN
            v_pk := JSON_VALUE(p_payload, '$.ti_iden');
            IF p_event_type IN ('DELETE','DELETED') THEN
                IF v_pk IS NOT NULL THEN
                    DELETE FROM PERSONAREFERENCIASBANCARIASTYPE WHERE IDENTIFICACION = v_pk;
                END IF;
            ELSIF v_pk IS NOT NULL THEN
                MERGE INTO PERSONAREFERENCIASBANCARIASTYPE t
                USING (SELECT v_pk AS k, '1' AS sec FROM dual) s
                ON (t.IDENTIFICACION = s.k AND t.SECUENCIAREFERENCIABANCARIA = s.sec)
                WHEN MATCHED THEN UPDATE SET CODIGOTIPOIDENTIFICACION = JSON_VALUE(p_payload,'$.ti_iden'), CODIGOTIPOCUENTAREFERENCIA = JSON_VALUE(p_payload,'$.ti_cnta'), TIPOIDENTIFICACIONIFINANCIERA = JSON_VALUE(p_payload,'$.ti_iden'), IDENTIFICACIONIFINANCIERA = JSON_VALUE(p_payload,'$.ti_iden'), NUCEMPRESABANCARIA = JSON_VALUE(p_payload,'$.co_empr'), CODIGOCUENTA = JSON_VALUE(p_payload,'$.nu_cnta'), NOMBRETITULAR = NULL, NUMEROCIFRAS = NULL, CODIGOCIFRASALDO = NULL, FECHAAPERTURA = NULL, NUMEROPROTESTOS = NULL, CERRADA = NULL, NOMBREINSTITUCIONPARACACEL = NULL, OBSERVACIONESSOLOPARACACEL = NULL
                WHEN NOT MATCHED THEN INSERT (CODIGOTIPOIDENTIFICACION, IDENTIFICACION, SECUENCIAREFERENCIABANCARIA, CODIGOTIPOCUENTAREFERENCIA, TIPOIDENTIFICACIONIFINANCIERA, IDENTIFICACIONIFINANCIERA, NUCEMPRESABANCARIA, CODIGOCUENTA, NOMBRETITULAR, NUMEROCIFRAS, CODIGOCIFRASALDO, FECHAAPERTURA, NUMEROPROTESTOS, CERRADA, NOMBREINSTITUCIONPARACACEL, OBSERVACIONESSOLOPARACACEL) VALUES (JSON_VALUE(p_payload,'$.ti_iden'), JSON_VALUE(p_payload,'$.ti_iden'), NULL, JSON_VALUE(p_payload,'$.ti_cnta'), JSON_VALUE(p_payload,'$.ti_iden'), JSON_VALUE(p_payload,'$.ti_iden'), JSON_VALUE(p_payload,'$.co_empr'), JSON_VALUE(p_payload,'$.nu_cnta'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_err := SQLERRM;
            INSERT INTO CDC_INBOX_ERRORS (INBOX_ID, AGGREGATE_TYPE, EVENT_TYPE, ERROR_MESSAGE)
            VALUES (p_id, p_aggregate_type, p_event_type, 'PERSONAREFERENCIASBANCARIASTYPE: ' || SUBSTR(v_err,1,3900));
        END;
    END IF;


    -- personaType  <-  cgtbprvd  ->  PERSONATYPE
    IF p_aggregate_type = 'personaType' AND p_source_table = 'cgtbprvd' THEN
        BEGIN
            v_pk := JSON_VALUE(p_payload, '$.ti_iden');
            IF p_event_type IN ('DELETE','DELETED') THEN
                IF v_pk IS NOT NULL THEN
                    DELETE FROM PERSONATYPE WHERE IDENTIFICACION = v_pk;
                END IF;
            ELSIF v_pk IS NOT NULL THEN
                MERGE INTO PERSONATYPE t
                USING (SELECT v_pk AS k FROM dual) s
                ON (t.IDENTIFICACION = s.k)
                WHEN MATCHED THEN UPDATE SET CODIGOTIPOIDENTIFICACION = JSON_VALUE(p_payload,'$.ti_iden'), CODIGOTIPOPERSONA = JSON_VALUE(p_payload,'$.ti_pers'), CODIGOSECTORECONOMICO = NULL, PRIMERAPELLIDO = NULL, SEGUNDOAPELLIDO = JSON_VALUE(p_payload,'$.in_segu'), PRIMERNOMBRE = NULL, SEGUNDONOMBRE = JSON_VALUE(p_payload,'$.in_segu'), NOMBRELEGAL = NULL, FECHAINGRESO = JSON_VALUE(p_payload,'$.fe_ingr'), CODIGOPAIS = NULL, CODIGORESIDENCIA = JSON_VALUE(p_payload,'$.ti_iden'), CODIGOACTIVIDAD = NULL, CODIGOACTIVIDADDETALLE = NULL, OBSERVACIONES = NULL, SUCURSALINGRESO = JSON_VALUE(p_payload,'$.fe_ingr'), OFICINAINGRESO = JSON_VALUE(p_payload,'$.fe_ingr'), CODIGOESTATUSPERSONA = JSON_VALUE(p_payload,'$.st_prvd'), NUMEROSOCIO = NULL, CODIGOUSUARIOOFICIALPERSONA = JSON_VALUE(p_payload,'$.ti_pers'), CODIGOCATEGORIATRATO = NULL, CODIGORAZONAPERTURAFINALIDAD = NULL, SUJETOOBLIGADO = NULL, NOMBREPREFERIDO = NULL, EXONERADOIMPUESTO = NULL, FECHACALIFICADO = NULL
                WHEN NOT MATCHED THEN INSERT (CODIGOTIPOIDENTIFICACION, IDENTIFICACION, CODIGOTIPOPERSONA, CODIGOSECTORECONOMICO, PRIMERAPELLIDO, SEGUNDOAPELLIDO, PRIMERNOMBRE, SEGUNDONOMBRE, NOMBRELEGAL, FECHAINGRESO, CODIGOPAIS, CODIGORESIDENCIA, CODIGOACTIVIDAD, CODIGOACTIVIDADDETALLE, OBSERVACIONES, SUCURSALINGRESO, OFICINAINGRESO, CODIGOESTATUSPERSONA, NUMEROSOCIO, CODIGOUSUARIOOFICIALPERSONA, CODIGOCATEGORIATRATO, CODIGORAZONAPERTURAFINALIDAD, SUJETOOBLIGADO, NOMBREPREFERIDO, EXONERADOIMPUESTO, FECHACALIFICADO) VALUES (JSON_VALUE(p_payload,'$.ti_iden'), JSON_VALUE(p_payload,'$.ti_iden'), JSON_VALUE(p_payload,'$.ti_pers'), NULL, NULL, JSON_VALUE(p_payload,'$.in_segu'), NULL, JSON_VALUE(p_payload,'$.in_segu'), NULL, JSON_VALUE(p_payload,'$.fe_ingr'), NULL, JSON_VALUE(p_payload,'$.ti_iden'), NULL, NULL, NULL, JSON_VALUE(p_payload,'$.fe_ingr'), JSON_VALUE(p_payload,'$.fe_ingr'), JSON_VALUE(p_payload,'$.st_prvd'), NULL, JSON_VALUE(p_payload,'$.ti_pers'), NULL, NULL, NULL, NULL, NULL, NULL);
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_err := SQLERRM;
            INSERT INTO CDC_INBOX_ERRORS (INBOX_ID, AGGREGATE_TYPE, EVENT_TYPE, ERROR_MESSAGE)
            VALUES (p_id, p_aggregate_type, p_event_type, 'PERSONATYPE: ' || SUBSTR(v_err,1,3900));
        END;
    END IF;


    -- auditoriaAfiliadoType  <-  cttbafil_audi  ->  AUDITORIAAFILIADO_TYPE
    IF p_aggregate_type = 'auditoriaAfiliadoType' AND p_source_table = 'cttbafil_audi' THEN
        BEGIN
            v_pk := JSON_VALUE(p_payload, '$.ci_cedula');
            IF p_event_type IN ('DELETE','DELETED') THEN
                IF v_pk IS NOT NULL THEN
                    DELETE FROM AUDITORIAAFILIADO_TYPE WHERE IDENTIFICACION = v_pk;
                END IF;
            ELSIF v_pk IS NOT NULL THEN
                MERGE INTO AUDITORIAAFILIADO_TYPE t
                USING (SELECT v_pk AS k, JSON_VALUE(p_payload,'$.ds_audi') AS sec FROM dual) s
                ON (t.IDENTIFICACION = s.k AND t.SECUENCIAAUDITORIA = s.sec)
                WHEN MATCHED THEN UPDATE SET CODIGOTIPOIDENTIFICACION = NULL, FECHAMODIFICACION = NULL, CAMPOMODIFICADO = JSON_VALUE(p_payload,'$.ci_camp'), VALORANTERIOR = NULL, VALORNUEVO = NULL, CODIGOUSUARIO = JSON_VALUE(p_payload,'$.co_usua'), TIPOOPERACION = NULL, ORIGENMODIFICACION = NULL, ESTADO = NULL, CODIGOCUENTA = NULL, TIPOIDENTIFICACION = NULL, RELACIONPRODUCTO = NULL, CODIGOEMPRESA = NULL, SECUENCIAACTUALIZACION = NULL, NUMEROCEDULARECIBECOREO = JSON_VALUE(p_payload,'$.ci_cedula'), NUMEROTELEFONOCONVENCIONAL = NULL, NUMEROTELEFONOCELULAR = NULL, DIRECCIONPATRONO = NULL, DESCRIPCIONINSTITUCION = NULL, USUARIOINGRESA = JSON_VALUE(p_payload,'$.co_usua'), FECHACREACION = JSON_VALUE(p_payload,'$.fe_crea'), HORAINGRESO = NULL, CODIGOCAMPOAMODIFICAR = JSON_VALUE(p_payload,'$.ci_camp'), NOMBRECAMPOAMODIFICAR = JSON_VALUE(p_payload,'$.ci_camp'), DESCRIPCIONCAMPOAMODIFICAR = JSON_VALUE(p_payload,'$.ci_camp'), HORACREACION = JSON_VALUE(p_payload,'$.fe_crea'), DESCRIPCIONADICIONAL = NULL, CODIGOMOTIVOMANTENIMIENTO = JSON_VALUE(p_payload,'$.ci_moti'), NUMEROTRANSACCION = NULL, CODIGOTRANSACCIONUTILIZADA = NULL, HORAGENERACIONREGISTRO = NULL, INDICADORCONTRATOCESANTIA = NULL, NIVELAPORTE = NULL, VALORDESCUENTOHIPOTECARIO = NULL, CODIGOCATEGORIA = NULL, CEDULACOORDINADOR = JSON_VALUE(p_payload,'$.ci_cedula'), PORCENTAJECAM = NULL, PORCENTAJEFUNCIONAL = NULL
                WHEN NOT MATCHED THEN INSERT (CODIGOTIPOIDENTIFICACION, IDENTIFICACION, SECUENCIAAUDITORIA, FECHAMODIFICACION, CAMPOMODIFICADO, VALORANTERIOR, VALORNUEVO, CODIGOUSUARIO, TIPOOPERACION, ORIGENMODIFICACION, ESTADO, CODIGOCUENTA, TIPOIDENTIFICACION, RELACIONPRODUCTO, CODIGOEMPRESA, SECUENCIAACTUALIZACION, NUMEROCEDULARECIBECOREO, NUMEROTELEFONOCONVENCIONAL, NUMEROTELEFONOCELULAR, DIRECCIONPATRONO, DESCRIPCIONINSTITUCION, USUARIOINGRESA, FECHACREACION, HORAINGRESO, CODIGOCAMPOAMODIFICAR, NOMBRECAMPOAMODIFICAR, DESCRIPCIONCAMPOAMODIFICAR, HORACREACION, DESCRIPCIONADICIONAL, CODIGOMOTIVOMANTENIMIENTO, NUMEROTRANSACCION, CODIGOTRANSACCIONUTILIZADA, HORAGENERACIONREGISTRO, INDICADORCONTRATOCESANTIA, NIVELAPORTE, VALORDESCUENTOHIPOTECARIO, CODIGOCATEGORIA, CEDULACOORDINADOR, PORCENTAJECAM, PORCENTAJEFUNCIONAL) VALUES (NULL, JSON_VALUE(p_payload,'$.ci_cedula'), JSON_VALUE(p_payload,'$.ds_audi'), NULL, JSON_VALUE(p_payload,'$.ci_camp'), NULL, NULL, JSON_VALUE(p_payload,'$.co_usua'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, JSON_VALUE(p_payload,'$.ci_cedula'), NULL, NULL, NULL, NULL, JSON_VALUE(p_payload,'$.co_usua'), JSON_VALUE(p_payload,'$.fe_crea'), NULL, JSON_VALUE(p_payload,'$.ci_camp'), JSON_VALUE(p_payload,'$.ci_camp'), JSON_VALUE(p_payload,'$.ci_camp'), JSON_VALUE(p_payload,'$.fe_crea'), NULL, JSON_VALUE(p_payload,'$.ci_moti'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, JSON_VALUE(p_payload,'$.ci_cedula'), NULL, NULL);
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_err := SQLERRM;
            INSERT INTO CDC_INBOX_ERRORS (INBOX_ID, AGGREGATE_TYPE, EVENT_TYPE, ERROR_MESSAGE)
            VALUES (p_id, p_aggregate_type, p_event_type, 'AUDITORIAAFILIADO_TYPE: ' || SUBSTR(v_err,1,3900));
        END;
    END IF;


    -- distribucionAfiliadoType  <-  cttbmatr_dist_afil  ->  DISTRIBUCIONAFILIADO_TYPE
    IF p_aggregate_type = 'distribucionAfiliadoType' AND p_source_table = 'cttbmatr_dist_afil' THEN
        BEGIN
            v_pk := JSON_VALUE(p_payload, '$.Circuito');
            IF p_event_type IN ('DELETE','DELETED') THEN
                IF v_pk IS NOT NULL THEN
                    DELETE FROM DISTRIBUCIONAFILIADO_TYPE WHERE CIRCUITO = v_pk;
                END IF;
            ELSIF v_pk IS NOT NULL THEN
                MERGE INTO DISTRIBUCIONAFILIADO_TYPE t
                USING (SELECT v_pk AS k FROM dual) s
                ON (t.CIRCUITO = s.k)
                WHEN MATCHED THEN UPDATE SET CIUDAD = JSON_VALUE(p_payload,'$.Ciudad'), DISTRITO = JSON_VALUE(p_payload,'$.Distrito'), ESTADODISTRIBUCIONAFILIADO = JSON_VALUE(p_payload,'$.Estado'), MONTOCREDITOVIGENTE = NULL, MONTOCUENTAUNICA = NULL, NOMBREPROVINCIA = JSON_VALUE(p_payload,'$.Provincia'), NUMEROAFILIADO = JSON_VALUE(p_payload,'$.NumeroAfiliado'), NUMEROAFILIADOACTUALIZADO = JSON_VALUE(p_payload,'$.NumeroAfiliado'), NUMEROCADB = JSON_VALUE(p_payload,'$.NumeroCADB'), NUMEROCAP = JSON_VALUE(p_payload,'$.NumeroCAP'), NUMEROCREDITOVIGENTE = JSON_VALUE(p_payload,'$.NumeroCreditoVigente'), NUMERODIRECTIVONACIONAL2008 = JSON_VALUE(p_payload,'$.NumeroDirectivoNacional2008'), NUMERODIRECTIVONACIONAL2010 = JSON_VALUE(p_payload,'$.NumeroDirectivoNacional2010'), NUMERODIRECTIVOPROVINCIAL2008 = JSON_VALUE(p_payload,'$.Provincia'), NUMERODIRECTIVOPROVINCIAL2010 = JSON_VALUE(p_payload,'$.Provincia'), NUMEROEJECUTIVOFINANCIERO = JSON_VALUE(p_payload,'$.NumeroEjecutivoFinanciero'), NUMEROINSTITUCIONES = JSON_VALUE(p_payload,'$.NumeroInstituciones'), NUMEROLEGADOCONVENCION2008 = NULL, NUMEROLEGADOCONVENCION2010 = NULL, NUMEROLIDEROPINION = NULL, NUMEROPRESIDENTEEJECUTIVO2008 = JSON_VALUE(p_payload,'$.NumeroPresidenteEjecutivo2008'), NUMEROPRESIDENTEEJECUTIVO2010 = JSON_VALUE(p_payload,'$.NumeroPresidenteEjecutivo2010'), NUMEROPRESIDENTESPROVINCIALES2008 = JSON_VALUE(p_payload,'$.Provincia'), NUMEROPRESIDENTESPROVINCIALES2010 = JSON_VALUE(p_payload,'$.Provincia'), NUMEROSOLOCAM = NULL, DESCRIPCIONPARROQUIA = JSON_VALUE(p_payload,'$.Parroquia'), TRABAJO = JSON_VALUE(p_payload,'$.trabajo'), ZONA = JSON_VALUE(p_payload,'$.Zona')
                WHEN NOT MATCHED THEN INSERT (CIRCUITO, CIUDAD, DISTRITO, ESTADODISTRIBUCIONAFILIADO, MONTOCREDITOVIGENTE, MONTOCUENTAUNICA, NOMBREPROVINCIA, NUMEROAFILIADO, NUMEROAFILIADOACTUALIZADO, NUMEROCADB, NUMEROCAP, NUMEROCREDITOVIGENTE, NUMERODIRECTIVONACIONAL2008, NUMERODIRECTIVONACIONAL2010, NUMERODIRECTIVOPROVINCIAL2008, NUMERODIRECTIVOPROVINCIAL2010, NUMEROEJECUTIVOFINANCIERO, NUMEROINSTITUCIONES, NUMEROLEGADOCONVENCION2008, NUMEROLEGADOCONVENCION2010, NUMEROLIDEROPINION, NUMEROPRESIDENTEEJECUTIVO2008, NUMEROPRESIDENTEEJECUTIVO2010, NUMEROPRESIDENTESPROVINCIALES2008, NUMEROPRESIDENTESPROVINCIALES2010, NUMEROSOLOCAM, DESCRIPCIONPARROQUIA, TRABAJO, ZONA) VALUES (JSON_VALUE(p_payload,'$.Circuito'), JSON_VALUE(p_payload,'$.Ciudad'), JSON_VALUE(p_payload,'$.Distrito'), JSON_VALUE(p_payload,'$.Estado'), NULL, NULL, JSON_VALUE(p_payload,'$.Provincia'), JSON_VALUE(p_payload,'$.NumeroAfiliado'), JSON_VALUE(p_payload,'$.NumeroAfiliado'), JSON_VALUE(p_payload,'$.NumeroCADB'), JSON_VALUE(p_payload,'$.NumeroCAP'), JSON_VALUE(p_payload,'$.NumeroCreditoVigente'), JSON_VALUE(p_payload,'$.NumeroDirectivoNacional2008'), JSON_VALUE(p_payload,'$.NumeroDirectivoNacional2010'), JSON_VALUE(p_payload,'$.Provincia'), JSON_VALUE(p_payload,'$.Provincia'), JSON_VALUE(p_payload,'$.NumeroEjecutivoFinanciero'), JSON_VALUE(p_payload,'$.NumeroInstituciones'), NULL, NULL, NULL, JSON_VALUE(p_payload,'$.NumeroPresidenteEjecutivo2008'), JSON_VALUE(p_payload,'$.NumeroPresidenteEjecutivo2010'), JSON_VALUE(p_payload,'$.Provincia'), JSON_VALUE(p_payload,'$.Provincia'), NULL, JSON_VALUE(p_payload,'$.Parroquia'), JSON_VALUE(p_payload,'$.trabajo'), JSON_VALUE(p_payload,'$.Zona'));
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_err := SQLERRM;
            INSERT INTO CDC_INBOX_ERRORS (INBOX_ID, AGGREGATE_TYPE, EVENT_TYPE, ERROR_MESSAGE)
            VALUES (p_id, p_aggregate_type, p_event_type, 'DISTRIBUCIONAFILIADO_TYPE: ' || SUBSTR(v_err,1,3900));
        END;
    END IF;


    -- auditoriaAfiliadoType  <-  cttbtabl_afil  ->  AUDITORIAAFILIADO_TYPE
    IF p_aggregate_type = 'auditoriaAfiliadoType' AND p_source_table = 'cttbtabl_afil' THEN
        BEGIN
            v_pk := JSON_VALUE(p_payload, '$.ci_camp');
            IF p_event_type IN ('DELETE','DELETED') THEN
                IF v_pk IS NOT NULL THEN
                    DELETE FROM AUDITORIAAFILIADO_TYPE WHERE CAMPOMODIFICADO = v_pk;
                END IF;
            ELSIF v_pk IS NOT NULL THEN
                MERGE INTO AUDITORIAAFILIADO_TYPE t
                USING (SELECT v_pk AS k, '1' AS sec FROM dual) s
