                WHEN NOT MATCHED THEN INSERT (CODIGOSECUENCIACAUSAFALLECIMIENTO, DESCRIPCIONCAUSAFALLECIMIENTO, ESTADOCAUSA, FECHACREACION, FECHAMODIFICACION, USUARIOINGRESA, USUARIOMODIFICA, CODIGOFONDO, CODIGOTIPOFAMILIAR, CODIGOTIPOPLAN, EDADPROVEEDOR, ESTADOCOBERTURA, FECHAAFILIACIONCAM, FECHAFINALVIGENCIATASA, FECHAINICIO, MONTOCOBERTURA, NUMEROANIOSAFILIACIONFCME, TIPOCOBERTURA, CODIGODISCAPACIDADFAMILIARES, DISCAPACIDADFAMILIARESAFILIADO, ESTADODISCAPACIDAD, CODIGOEFECTO, DESCRIPCIONEFECTO, ESTADOEFECTO, TIPOEFECTO, DESCRIPCIONFORMAPAGO, ESTADOFORMAPAGO, TIPOFORMAPAGO, CEDULAIDENTIDADAFILIADO, CEDULAIDENTIDADSINIESTRADO, CODIGOBANCOELCUALREALIZAPAGO, CODIGOEMPRESA, CODIGOPROVINCIA, CODIGOUSUARIOCONFIRMA, ESTADOANTERIORSINIESTRADO, ESTADOSINESTRO, FECHAAUTORIZACION, FECHAELIMINACION, FECHAFALLECIMIENTO, FECHANOTIFICACIONSINIESTRO, FECHAPRESENTACIONPAPELESSINIESTRADO, FECHAVERIFICACION, SECUENCIASINIESTRO, TIPOSINIESTRO, USUARIOAUTORIZACION, USUARIOELIMINA, CEDULABENEFICIARIO, CODIGOTIPOFAMILIARSINIESTRADO, MONTOQUERECIBIOBENEFICIARIO, PORCENTAJEDISTRUBUCION, ABONOPROPUESTOCREDITODESGRAVAMEN, ANIOCREDITO, INDICADORPAGODESGRAVAMEN, MONTOCREDITOACANCELAR, MONTOPAGARSOBREGIROOTROFONDO, SECUENCIACREDITO, TIPOCREDITO, VALORDESGRAVAMEN, MONTOCUBIERTOPORDESGRAVAMEN, MONTONOCUBIERTOCREDITO, MONTOPAGOSOBREGIROOTROFONDO, MONTOPARACUBRIRSALDOCREDITO, MONTOREALAPERCIBIRPORSINIESTRO, ESTADOSINIESTROEXTEMPORANEO, FECHASINIESTRO) VALUES (NULL, NULL, NULL, NULL, NULL, JSON_VALUE(p_payload,'$.fe_ingr'), NULL, NULL, NULL, NULL, NULL, NULL, JSON_VALUE(p_payload,'$.co_afil'), NULL, NULL, NULL, JSON_VALUE(p_payload,'$.co_afil'), NULL, NULL, JSON_VALUE(p_payload,'$.co_afil'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, JSON_VALUE(p_payload,'$.co_afil'), NULL, NULL, NULL, NULL, NULL, NULL, JSON_VALUE(p_payload,'$.co_sine'), NULL, JSON_VALUE(p_payload,'$.fe_elim'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, JSON_VALUE(p_payload,'$.fe_elim'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_err := SQLERRM;
            INSERT INTO CDC_INBOX_ERRORS (INBOX_ID, AGGREGATE_TYPE, EVENT_TYPE, ERROR_MESSAGE)
            VALUES (p_id, p_aggregate_type, p_event_type, 'SEGUROVIDAPARTICIPE_TYPE: ' || SUBSTR(v_err,1,3900));
